const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tracks=['봉인된 밤','비어 있는 액자','자정의 신호','잉크의 흔적','유리 온실','결승 전야','설원에 남은 침묵','마지막 주파수','봉인 번호','7분의 공백'];
const WRONG='오답입니다. 진실 아직 밝혀지지 않았습니다';
const dimensions=[['core','핵심 상황',30],['cause','원인·동기',20],['sequence','사건 재구성',25],['evidence','근거 연결',15],['process','질문·추리 과정',10]];
const state={me:null,game:null,catalog:[],busy:false,rankings:[],voice:null,tts:'browser',musicOn:false,ducked:false,volume:.22};
const modal=$('#modal'),bgm=$('#bgm'),audio=$('#ai-audio');let toastTimer,voiceWatchdog,loadedGameId=null;
const sessionGet=k=>{try{return sessionStorage.getItem(k)}catch{return null}},sessionSet=(k,v)=>{try{sessionStorage.setItem(k,v)}catch{}},sessionRemove=k=>{try{sessionStorage.removeItem(k)}catch{}};
try{const prefs=JSON.parse(localStorage.getItem('profiler.audio')||'{}');state.volume=typeof prefs.volume==='number'?Math.max(0,Math.min(1,prefs.volume)):.22;state.voice=prefs.voice||null;state.tts=prefs.tts==='openai'?'openai':'browser'}catch{}
$('#music-volume').value=Math.round(state.volume*100);
function savePrefs(){try{localStorage.setItem('profiler.audio',JSON.stringify({volume:state.volume,voice:state.voice,tts:state.tts}))}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5500)}
function show(html,wide=false){$('#modal-content').innerHTML=html;modal.classList.toggle('wide',wide);if(!modal.open)modal.showModal()}
async function api(url,{method='GET',body}={}){const r=await fetch(url,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json()}catch{throw new Error('서버 응답을 읽지 못했습니다. 다시 시도해 주세요.')}if(!r.ok)throw new Error(data.error||'요청에 실패했습니다.');return data}
async function action(fn){try{return await fn()}catch(e){toast(e.message)}}
const currentCase=()=>state.game?.case||state.catalog[0];
const draftKey=()=>`profiler.draft.${state.game?.id}`;
function applyVolume(){bgm.volume=state.volume*(state.ducked?.18:1)}
function duck(on){state.ducked=on;applyVolume()}
async function playMusic(){if(!bgm.src)bgm.src=`/audio/${currentCase()?.id||'case-01'}.wav`;applyVolume();try{await bgm.play();state.musicOn=true;$('#music-toggle').textContent='Ⅱ';$('.equalizer').classList.add('playing')}catch{toast('배경음 재생 버튼을 눌러 소리를 켜주세요.')}}
function stopMusic(){bgm.pause();state.musicOn=false;$('#music-toggle').textContent='▷';$('.equalizer').classList.remove('playing')}
function selectTrack(id){const src=`/audio/${id}.wav`;if(new URL(bgm.src||location.href).pathname!==src){bgm.src=src;if(state.musicOn)void playMusic()}$('#track-name').textContent=tracks[Number(id.slice(-2))-1];applyVolume()}
function availableVoices(){return window.speechSynthesis?.getVoices()||[]}
function chooseVoice(){const voices=availableVoices(),ko=voices.filter(v=>/^ko/i.test(v.lang));return voices.find(v=>v.voiceURI===state.voice)||ko.find(v=>/male|남성|injoon|hyunsu|bongjin/i.test(v.name))||ko[0]}
function stopSpeech(){window.speechSynthesis?.cancel();audio.pause();audio.removeAttribute('src');clearTimeout(voiceWatchdog);duck(false)}
function speak(text,{intro=false}={}){stopSpeech();if(!window.speechSynthesis){toast('이 브라우저는 음성 읽기를 지원하지 않습니다.');return}const u=new SpeechSynthesisUtterance(text);u.lang='ko-KR';const voice=chooseVoice();if(voice)u.voice=voice;u.rate=intro?.86:.94;u.pitch=intro?.68:.9;u.volume=1;u.onstart=()=>duck(true);u.onend=()=>{clearTimeout(voiceWatchdog);duck(false)};u.onerror=()=>{clearTimeout(voiceWatchdog);duck(false)};voiceWatchdog=setTimeout(()=>duck(false),50000);speechSynthesis.speak(u)}
async function verdictVoice(text){if(!$('#voice-enabled').checked)return;if(state.tts==='browser'){speak(text);return}stopSpeech();duck(true);audio.src=`/api/tts/${encodeURIComponent(text)}`;audio.onended=()=>duck(false);audio.onerror=()=>{duck(false);toast('OpenAI 음성 연결을 확인해 주세요. 브라우저 음성으로 읽습니다.');speak(text)};try{await audio.play()}catch{duck(false);toast('응답 옆 듣기 버튼을 눌러 음성을 재생하세요.')}}
function setBusy(on,kind=''){state.busy=on;state.busyKind=kind;renderControls()}
function renderControls(){const active=!!state.game&&state.game.status!=='completed',completed=state.game?.status==='completed';const locked=state.busy;$('#question').disabled=!active||locked||state.game.questions.length>=40;$('#ask').disabled=$('#question').disabled;$('#final-answer').disabled=!active||locked;$('#final-submit').disabled=!active||locked;$('#final-submit').textContent=locked&&state.busyKind==='submit'?'사건 해석 분석 중…':'해석 제출 ↗';$('#start').disabled=locked;$('#start').innerHTML=completed?'다음 랜덤 사건 <span>↗</span>':state.game?'사건 계속 수사하기 <span>↗</span>':'랜덤 사건 시작 <span>↗</span>';$('#ai-status').textContent=locked?(state.busyKind==='submit'?'해석 분석 중…':'질문 확인 중…'):active?'수사 진행 중':completed?'수사 완료':'대기 중';$('#account').textContent=state.me?.user?`${state.me.user.name} ↗`:'치지직 로그인 ↗';$('#attempt-badge').textContent=completed?(state.game.solved?'진실 규명 완료':'제출 기회 종료'):`제출 기회 ${state.game?.attemptsLeft??3} / 3`;$('#view-report').hidden=!completed;$('#answer-form').hidden=!!completed}
function feedback(message,correct=false){$('#answer-feedback').hidden=!message;$('#answer-feedback').textContent=message;$('#answer-feedback').classList.toggle('correct',correct)}
function renderCase(){const c=currentCase();if(!c)return;$('#scene-image').src=`/images/${c.id}.png`;$('#scene-image').alt=`${c.title} — AI가 제작한 사건 현장 재현`;$('#case-title').textContent=c.title;$('#case-scene').textContent=c.scene;$('#file-id').textContent=`FILE / ${c.id.slice(-2).padStart(3,'0')}`;$('#difficulty').textContent=c.difficulty;selectTrack(c.id);renderConversation();if(loadedGameId!==state.game?.id){loadedGameId=state.game?.id;$('#final-answer').value=state.game?sessionGet(draftKey())||'':'';$('#question').value='';updateAnswerLength();feedback('')}
  if(state.game?.attempts.length&&state.game.status!=='completed'){feedback(`${WRONG} · 남은 기회 ${state.game.attemptsLeft}회`)}renderControls()}
function renderConversation(){const rows=state.game?.questions||[];$('#question-count').textContent=`${rows.length} / 40`;if(!rows.length){$('#conversation').innerHTML='<div class="empty-investigation"><span class="empty-symbol">?</span><h3>어떤 질문부터 시작할까요?</h3><p>“사라진 물건은 아직 건물 안에 있나요?”<br>하나의 가설을 담아 질문해 보세요.</p></div>';return}$('#conversation').innerHTML=rows.map((q,i)=>`<div class="exchange"><div class="q-number">QUESTION ${String(i+1).padStart(2,'0')}</div><p class="question-bubble">${esc(q.question)}</p><div class="verdict ${q.verdict==='맞습니다'?'yes':q.verdict==='아닙니다'?'no':'maybe'}"><span class="ai-mark">◎</span><strong>${esc(q.verdict)}</strong><button data-speak="${esc(q.verdict)}" aria-label="응답 다시 듣기">▷</button></div></div>`).join('');$('#conversation').scrollTop=$('#conversation').scrollHeight}
async function loadGame(id){state.game=await api(`/api/games/${id}`);renderCase()}
async function refreshArchive(){if(!state.me?.user){$('#archive-list').innerHTML='<div class="empty-panel">치지직으로 로그인하면 수사 기록을 확인할 수 있습니다.</div>';return}const data=await api('/api/games'),completed=data.games.filter(g=>g.status==='completed').length;$('#progress').textContent=`시즌 01 · ${completed} / 10 사건 완료`;$('#archive-list').innerHTML=data.games.length?data.games.map(g=>`<button class="archive-card" data-game="${g.id}"><img src="/images/${g.case_id}.png" alt="" loading="lazy"><div><small>${g.case_id.toUpperCase()} · ${new Date(Number(g.created_at)).toLocaleDateString('ko-KR')}</small><h3>${esc(g.title)}</h3><p>${g.status==='completed'?`${g.solved?'해결':'미해결'} · ${g.score}점 · 오답 ${g.wrongCount}회`:`수사 중 · 제출 ${g.attemptCount} / 3회`}</p></div><b class="archive-grade">${esc(g.grade||'…')}</b></button>`).join(''):'<div class="empty-panel">아직 기록이 없습니다. 첫 사건을 시작해 보세요.</div>';return data}
async function refreshRanks(){const data=await api('/api/rankings');state.rankings=data.rankings;$('#rank-body').innerHTML=data.rankings.length?data.rankings.map((r,i)=>`<tr><td class="rank-num">${String(i+1).padStart(2,'0')}</td><td>${esc(r.name)}</td><td class="points">${Number(r.points).toLocaleString()}</td><td>${Number(r.average).toFixed(1)}</td><td>${r.solved} / ${r.games}</td><td>${r.best}</td></tr>`).join(''):'<tr><td colspan="6" class="empty-cell">아직 완료된 수사가 없습니다. 첫 번째 기록의 주인공이 되어 보세요.</td></tr>'}
function view(name){for(const id of ['game','rank','archive'])$(`#view-${id}`).hidden=id!==name;$$('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='rank')void action(refreshRanks);if(name==='archive')void action(refreshArchive)}
function report(){const g=state.game,r=g?.report;if(!r)return;show(`<div class="report-top"><div><span class="eyebrow">INVESTIGATION REPORT / ${esc(g.case.id)}</span><h2>${esc(r.title)}</h2><p>${esc(state.me.user.name)} · ${esc(g.case.title)}<br>${g.solved?'진실 규명':'미해결'} · ${g.attempts.length}회 제출 · 오답 ${g.attempts.filter(a=>!a.correct).length}회</p></div><div class="grade-seal"><b>${esc(r.grade)}</b><span>${r.score} / 100</span></div></div><p class="report-summary">${esc(r.summary)}</p><div class="dimension-grid">${dimensions.map(([key,label,max])=>`<div class="dimension"><div><strong>${label}</strong><span>${r[key].score} / ${max}</span></div><div class="meter"><span style="width:${r[key].score/max*100}%"></span></div><p>${esc(r[key].reason)}</p></div>`).join('')}</div>${r.capped?'<p class="report-caption">사건의 핵심 정답 기준에 도달하지 않아 총점 상한 69점이 적용되었습니다.</p>':''}<div class="report-columns"><div><h3>잘한 추리</h3><ul>${r.strengths.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div><div><h3>다음 수사를 위한 제안</h3><ul>${r.improvements.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div></div>${r.moments.length?`<h3>추리의 전환점</h3>${r.moments.map(m=>`<div class="moment"><small>질문 ${m.questionNumber}</small><blockquote>${esc(g.questions[m.questionNumber-1]?.question||'')}</blockquote><p>${esc(m.analysis)}</p></div>`).join('')}`:'<p class="small-muted">기록된 질문이 없어 질문 과정의 전환점을 분석하지 않았습니다.</p>'}<details class="solution" open><summary>실제로 일어난 일 · 정답 해설</summary><p>${esc(g.solution.overview)}</p><p><b>원인</b> ${esc(g.solution.cause)}</p><p><b>전개</b> ${esc(g.solution.sequence)}</p><p><b>근거</b> ${esc(g.solution.evidence)}</p></details><details class="solution"><summary>정답·오답 제출 히스토리 (${g.attempts.length}회)</summary>${g.attempts.map((a,i)=>`<div class="attempt-history"><b>${i+1}회차 · ${a.correct?'정답':'오답'}</b><p>${esc(a.answer)}</p></div>`).join('')}</details><details class="solution"><summary>전체 질문 기록 (${g.questions.length}개)</summary>${g.questions.map((q,i)=>`<div class="attempt-history"><b>질문 ${i+1} · ${esc(q.verdict)}</b><p>${esc(q.question)}</p></div>`).join('')}</details><p class="report-caption">이번 게임에 대한 AI 평가입니다. 실제 수사 능력이나 성격을 진단하지 않습니다. 기준 v${esc(r.rubricVersion)} · A 85+ / B 70+ / C 50+ / D 0+</p><div class="modal-actions"><button id="download-report" class="outline">분석지 저장 ↓</button><button id="print-report" class="outline">인쇄 / PDF</button><button id="report-next" class="lime">다음 사건 ↗</button></div>`,true);
  $('#download-report').onclick=()=>{const text=[`${g.case.title} — ${state.me.user.name}`,`${r.grade} 등급 / ${r.score}점 / ${g.solved?'해결':'미해결'}`,r.title,r.summary,...dimensions.map(([k,l,max])=>`${l}: ${r[k].score}/${max}\n${r[k].reason}`),'잘한 추리',...r.strengths,'개선할 점',...r.improvements,'추리의 전환점',...r.moments.map(m=>`질문 ${m.questionNumber}: ${g.questions[m.questionNumber-1].question}\n${m.analysis}`),'전체 질문',...g.questions.map((q,i)=>`${i+1}. ${q.question}\n${q.verdict}`),'제출 히스토리',...g.attempts.map((a,i)=>`${i+1}회 ${a.correct?'정답':'오답'}\n${a.answer}`),'정답',g.solution.overview,g.solution.cause,g.solution.sequence,g.solution.evidence,'이번 플레이에 한정된 AI 평가이며 실제 능력 진단이 아닙니다.'].join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`수사분석지-${g.case.id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
  $('#print-report').onclick=()=>{$$('#modal details').forEach(d=>d.open=true);window.print()};$('#report-next').onclick=()=>{modal.close();$('#start').click()};
}
function updateAnswerLength(){$('#answer-length').textContent=`${$('#final-answer').value.length} / 5000`}
$('#final-answer').oninput=e=>{updateAnswerLength();if(state.game)sessionSet(draftKey(),e.target.value)};
function requestBody(kind,text){const key=`profiler.pending.${kind}.${state.game.id}`;let previous;try{previous=JSON.parse(sessionGet(key))}catch{}if(previous?.text===text)return{key,requestId:previous.requestId};const requestId=crypto.randomUUID();sessionSet(key,JSON.stringify({text,requestId}));return{key,requestId}}
$('#answer-form').onsubmit=async e=>{e.preventDefault();if(state.busy||!state.game||state.game.status==='completed')return;const answer=$('#final-answer').value.trim();if(answer.length<10){feedback('사건의 전말을 최소 10자 이상 작성해 주세요.');return}const pending=requestBody('answer',answer),gameId=state.game.id;setBusy(true,'submit');feedback('질문 기록과 사건 해석을 비교하고 있습니다…');try{const result=await api(`/api/games/${gameId}/submit`,{method:'POST',body:{answer,requestId:pending.requestId}});sessionRemove(pending.key);await loadGame(gameId);feedback(result.correct?'정답입니다. 사건의 진실을 밝혀냈습니다.':`${WRONG} · ${result.completed?'세 번의 제출 기회가 끝났습니다.':`남은 기회 ${result.attemptsLeft}회`}`,result.correct);speak(result.correct?'정답입니다. 사건의 진실을 밝혀냈습니다.':WRONG,{intro:true});if(result.completed){sessionRemove(draftKey());report();void action(refreshRanks)}else{$('#final-answer').focus()}void action(refreshArchive)}catch(err){feedback(err.message)}finally{setBusy(false)}};
$('#question-form').onsubmit=async e=>{e.preventDefault();if(state.busy||!state.game)return;const question=$('#question').value.trim();if(question.length<2)return toast('두 글자 이상 질문해 주세요.');const pending=requestBody('question',question),gameId=state.game.id;setBusy(true,'question');try{const answer=await api(`/api/games/${gameId}/questions`,{method:'POST',body:{question,requestId:pending.requestId}});sessionRemove(pending.key);$('#question').value='';await loadGame(gameId);void verdictVoice(answer.verdict)}catch(err){toast(err.message)}finally{setBusy(false);$('#question').focus()}};
$('#question').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#question-form').requestSubmit()}};
$('#start').onclick=()=>action(async()=>{if(!state.me?.user)return showLogin();if(state.game&&state.game.status!=='completed'){view('game');$('#question').focus();return}setBusy(true);try{void playMusic();const g=await api('/api/games',{method:'POST',body:{}});state.game=g;renderCase();view('game');speak(g.case.scene,{intro:true});void action(refreshArchive)}finally{setBusy(false)}});
function showLogin(){show(`<span class="eyebrow">INVESTIGATOR SIGN IN</span><h2>당신의 수사를 기록하세요.</h2><p>치지직 계정으로 로그인하면 질문과 정답·오답 기록이 저장되고 사용자 랭킹에 참여할 수 있습니다.</p><a class="lime full link-button" href="/auth/chzzk">치지직으로 로그인 ↗</a>${state.me?.dev?'<button id="dev-login" class="outline full">로컬 테스트 계정으로 입장</button><p class="small-muted">테스트 계정은 사용자 랭킹에 반영되지 않습니다.</p>':''}`);if($('#dev-login'))$('#dev-login').onclick=()=>action(async()=>{await api('/api/dev-login',{method:'POST',body:{}});modal.close();await initialize()})}
$('#account').onclick=()=>{if(!state.me?.user)return showLogin();show(`<span class="eyebrow">INVESTIGATOR PROFILE</span><h2>${esc(state.me.user.name)}</h2><p>${state.me.user.verified?'치지직 인증 완료 · 수사 기록이 이 계정에 저장됩니다.':'로컬 테스트 계정 · 랭킹 제외'}</p><button id="logout" class="outline full">로그아웃</button>`);$('#logout').onclick=()=>action(async()=>{await api('/api/logout',{method:'POST',body:{}});state.game=null;loadedGameId=null;stopMusic();stopSpeech();$('#final-answer').value='';$('#question').value='';feedback('');modal.close();await initialize()})};
$('#conversation').onclick=e=>{const b=e.target.closest('[data-speak]');if(b)void verdictVoice(b.dataset.speak)};$('#view-report').onclick=report;
$('#read-scene').onclick=()=>currentCase()&&speak(currentCase().scene,{intro:true});$('#enlarge').onclick=()=>show(`<img class="scene-large" src="/images/${currentCase()?.id||'case-01'}.png" alt="확대된 AI 현장 재현"><p class="small-muted">AI 현장 재현 · 정확한 사실은 수사 질문으로 확인하세요.</p>`,true);
$('#music-toggle').onclick=()=>state.musicOn?stopMusic():void playMusic();$('#music-volume').oninput=e=>{state.volume=Number(e.target.value)/100;applyVolume();savePrefs()};
$('#sound-settings').onclick=()=>{const voices=availableVoices().filter(v=>/^ko/i.test(v.lang));show(`<span class="eyebrow">SOUND & VOICE</span><h2>사건실 오디오</h2><label class="field-label" for="voice-select">사건 소개 목소리 · 브라우저 TTS</label><select id="voice-select"><option value="">한국어 남성 음성 우선 선택</option>${voices.map(v=>`<option value="${esc(v.voiceURI)}" ${state.voice===v.voiceURI?'selected':''}>${esc(v.name)}</option>`).join('')}</select><p class="small-muted">기기에 남성 음성이 없으면 설치된 한국어 음성을 사용합니다. 소개와 정답·오답 안내는 낮은 음높이, 느린 속도로 읽습니다.</p><label class="field-label" for="tts-select">짧은 AI 질문 응답 읽기</label><select id="tts-select"><option value="browser" ${state.tts==='browser'?'selected':''}>브라우저 TTS · API 비용 없음</option><option value="openai" ${state.tts==='openai'?'selected':''}>OpenAI TTS · 서버 API 사용</option></select><p class="small-muted">재생되는 음성은 합성 음성입니다. 배경음은 사건별 오리지널 다크 앰비언트 10곡이며, 음성이 재생되면 자동으로 작아집니다.</p><div class="modal-actions"><button id="test-voice" class="outline">목소리 미리 듣기</button><button id="stop-voice" class="outline">음성 멈추기</button></div>`);$('#voice-select').onchange=e=>{state.voice=e.target.value;savePrefs()};$('#tts-select').onchange=e=>{state.tts=e.target.value;savePrefs()};$('#test-voice').onclick=()=>speak('사건 기록을 확인했습니다. 이제 당신의 수사를 시작하십시오.',{intro:true});$('#stop-voice').onclick=stopSpeech()};
$('#guide').onclick=()=>show('<span class="eyebrow">FIELD MANUAL</span><h2>진실을 재구성하는 방법</h2><ol class="guide-list"><li><b>랜덤 사건 시작</b><p>계정에서 아직 플레이하지 않은 사건을 뽑습니다. 10개를 완료하면 시즌이 끝납니다. 타이머는 없습니다.</p></li><li><b>위쪽 질문창으로 사건 알아가기</b><p>하나의 가설을 물어보세요. 사실이면 “맞습니다”, 모순이면 “아닙니다”, 미정·애매한 질문이면 “그럴 수도 있습니다”. 최대 40회입니다.</p></li><li><b>아래쪽 답안창으로 사건 해석 제출</b><p>실제로 무슨 일이 있었는지, 왜 그리고 어떻게 일어났는지 설명하세요. 이름 하나만 맞히는 게임이 아닙니다. 표현이 달라도 같은 의미면 인정됩니다.</p></li><li><b>오답은 최대 3번까지</b><p>1·2회차 오답은 정답을 공개하지 않고 질문을 이어갑니다. 정답을 맞히거나 3회차 오답이면 사건이 끝나고 분석지를 받습니다. API 오류는 기회를 차감하지 않습니다.</p></li></ol><p>핵심 상황 30 · 원인 20 · 전개 25 · 근거 15 · 추리 과정 10점. 핵심 24점, 원인 10점, 전개 15점 이상이면서 앞의 네 항목 합계 60점 이상이면 정답입니다. 정답 기준 미달 시 최고 C등급입니다.</p><p class="small-muted">A 85+ · B 70+ · C 50+ · D 0+. 한 사건의 최종 평가만 랭킹에 반영됩니다. 새로고침해도 질문과 제출 이력은 유지됩니다.</p>');
document.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)view(b.dataset.view);const g=e.target.closest('[data-game]');if(g&&!state.busy)void action(async()=>{await loadGame(g.dataset.game);view('game');if(state.game.status==='completed')report()})});$('#refresh-rank').onclick=()=>action(refreshRanks);$('#close-modal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});window.addEventListener('beforeunload',stopSpeech);
async function initialize(){state.me=await api('/api/me');state.catalog=(await api('/api/catalog')).cases;$('#notice').hidden=true;if(state.me.mock){$('#notice').hidden=false;$('#notice').textContent='로컬 테스트 모드 · 실제 AI 판정이 아닙니다. 테스트 답안에 “테스트정답”을 포함하면 성공 흐름을 확인할 수 있습니다. 랭킹에는 반영되지 않습니다.'}else if(!state.me.configured.ai||!state.me.configured.chzzk){$('#notice').hidden=false;$('#notice').textContent='연결 준비 중 · Railway에 OpenAI 키와 치지직 앱 정보를 설정하면 실제 수사를 시작할 수 있습니다.'}const archive=await refreshArchive();if(state.me.user){const active=archive?.games.find(g=>g.status!=='completed');if(active)await loadGame(active.id)}renderCase();await refreshRanks();const err=new URLSearchParams(location.search).get('authError');if(err){const messages={setup:'치지직 앱 환경변수를 먼저 설정해 주세요.',state:'로그인 요청이 만료되었습니다. 다시 시도해 주세요.',not_allowed:'이 채널은 참여 허용 목록에 없습니다.',connection:'치지직 로그인에 실패했습니다. 앱 권한과 리디렉션 URL을 확인하세요.'};toast(messages[err]||'로그인하지 못했습니다.');history.replaceState(null,'','/')}}
void action(initialize);
